internal static class ExpansionDeTerminos
{
    private static readonly Dictionary<string, string[]> TerminosRelacionados = new Dictionary<string, string[]>
    {
        ["defi"] = ["cort", "peso"],
        ["pond"] = ["defi", "cred"],
