using TutorFlow.Core.Autorizacion;
using TutorFlow.Core.Conocimiento;

namespace TutorFlow.Core.Asistente;

internal sealed record CierreEvaluado(
    string Texto,
    IReadOnlyList<Cita> Citas,
    ResultadoAuditoria Resultado,
    bool? UsoDatos,
    bool Bloqueado,
    string? MotivoDeReintento)
{
    public static CierreEvaluado Entregable(string texto, IReadOnlyList<Cita> citas, ResultadoAuditoria resultado, bool? usoDatos = null) =>
        new(texto, citas, resultado, usoDatos, false, null);
}

internal sealed class CierreDeRespuesta
{
    private readonly IBaseConocimiento _baseConocimiento;
    private readonly PoliticaAcceso _politicaAcceso;
    private readonly VerificadorSalida _verificadorSalida;
    private readonly ConfiguracionAsistente _configuracion;
    private readonly CitasDeRespuesta _citasDeRespuesta;
    private readonly CitasDeReglasAplicadas _citasDeReglas;
    private readonly AfirmacionesDePerdida _afirmacionesDePerdida;
    private readonly DefinitivaPorAsignatura _definitivaPorAsignatura;

    public CierreDeRespuesta(
        IBaseConocimiento baseConocimiento,
        PoliticaAcceso politicaAcceso,
        VerificadorSalida verificadorSalida,
        ConfiguracionAsistente configuracion)
    {
        _baseConocimiento = baseConocimiento;
        _politicaAcceso = politicaAcceso;
        _verificadorSalida = verificadorSalida;
        _configuracion = configuracion;
        _citasDeRespuesta = new CitasDeRespuesta(configuracion.ApoyoMinimoRespaldo);
        _definitivaPorAsignatura = new DefinitivaPorAsignatura(configuracion.Catalogo);
        _citasDeReglas = new CitasDeReglasAplicadas(baseConocimiento, _definitivaPorAsignatura);
        _afirmacionesDePerdida = new AfirmacionesDePerdida(configuracion.Catalogo);
    }

    public CierreEvaluado Evaluar(SesionPregunta sesion, string texto, EntradaConversacion entrada)
    {
        if (texto.Trim() == Textos.SinInformacion)
        {
            return CierreEvaluado.Entregable(Textos.SinInformacion, [], ResultadoAuditoria.SinInformacion);
        }

        var escritas = EscritasValidas(sesion, texto, entrada);
        var limpio = Textos.CitasDeTextoFijo(texto) is null ? ReferenciasEscritas.Limpiar(texto, escritas) : texto;
        return ReferenciasEscritas.TieneContenido(limpio)
            ? Verificar(sesion, limpio, escritas, entrada)
            : CierreEvaluado.Entregable(Textos.SinInformacion, [], ResultadoAuditoria.SinInformacion);
    }

    private IReadOnlyList<Cita> EscritasValidas(SesionPregunta sesion, string texto, EntradaConversacion entrada)
    {
        var usadas = _citasDeReglas.Usadas(sesion.Registro, ExtractorCitas.SinCitas(texto), sesion.Directorio);
        return _verificadorSalida.DescartarCitasInexistentes(
            _citasDeRespuesta.EscritasConApoyo(texto, entrada.Secciones, sesion.Registro.Reglas, usadas),
            _baseConocimiento);
    }

    private CierreEvaluado Verificar(SesionPregunta sesion, string limpio, IReadOnlyList<Cita> escritas, EntradaConversacion entrada)
    {
        var autorizados = _politicaAcceso.IdsPersonasAutorizadas(sesion.Entrada.Usuario, sesion.Directorio);
        var verificada = VerificarSalida(sesion, limpio, escritas, autorizados, entrada);
        if (verificada.Resultado != ResultadoAuditoria.Respondida)
        {
            return new CierreEvaluado(verificada.Respuesta, verificada.Citas, verificada.Resultado, null, true, verificada.MotivoDeReintento);
        }

        var motivo = MotivoDeAfirmacionNoVerificable(sesion, limpio, autorizados);
        return motivo is null
            ? Completar(sesion, limpio, escritas, entrada)
            : new CierreEvaluado(Textos.NoVerificable, [], ResultadoAuditoria.EstadoNoVerificado, null, true, motivo);
    }

    private SalidaVerificada VerificarSalida(SesionPregunta sesion, string limpio, IReadOnlyList<Cita> escritas, IReadOnlyCollection<string> autorizados, EntradaConversacion entrada) =>
        _verificadorSalida.Verificar(
            sesion.Entrada.Usuario,
            limpio,
            escritas,
            autorizados,
            sesion.Registro.Fuentes,
            _baseConocimiento,
            sesion.Directorio,
            Confidencial(sesion, entrada));

    private string? MotivoDeAfirmacionNoVerificable(SesionPregunta sesion, string respuesta, IReadOnlyCollection<string> autorizados)
    {
        var usuario = sesion.Entrada.Usuario;
        var bloques = BloquesDeRespuesta.De(respuesta);
        var resumenes = sesion.Registro.Resumenes;
        return _afirmacionesDePerdida.Motivo(bloques, usuario, autorizados, sesion.Directorio, resumenes)
            ?? _definitivaPorAsignatura.Motivo(bloques, usuario, autorizados, sesion.Directorio, resumenes);
    }

    private CierreEvaluado Completar(SesionPregunta sesion, string limpio, IReadOnlyList<Cita> escritas, EntradaConversacion entrada)
    {
        var citasDeTextoFijo = Textos.CitasDeTextoFijo(limpio);
        if (citasDeTextoFijo is not null)
        {
            return CierreEvaluado.Entregable(limpio, citasDeTextoFijo, ResultadoAuditoria.Respondida);
        }

        var documentos = CitasDeDocumento(sesion, limpio, escritas, entrada);
        if (documentos.Count == 0 && !sesion.Registro.UsoDatos)
        {
            return new CierreEvaluado(Textos.SinInformacion, [], ResultadoAuditoria.SinInformacion, false, true, null);
        }

        IReadOnlyList<Cita> citas = [.. documentos.Concat(sesion.Registro.Citas).Distinct()];
        return CierreEvaluado.Entregable(limpio, citas, ResultadoAuditoria.Respondida);
    }

    private IReadOnlyList<Cita> CitasDeDocumento(SesionPregunta sesion, string limpio, IReadOnlyList<Cita> escritas, EntradaConversacion entrada)
    {
        var usadas = _citasDeReglas.Usadas(sesion.Registro, limpio, sesion.Directorio);
        var vigentes = escritas.Where(cita => !sesion.Registro.Reglas.Contains(cita) || usadas.Contains(cita)).ToList();
        var reglas = _citasDeReglas.De(usadas, sesion.Entrada.Pregunta, vigentes);
        IReadOnlyList<Cita> sinRespaldo = [.. vigentes.Concat(reglas).Concat(_citasDeRespuesta.PorTema(limpio, entrada.Secciones)).Distinct()];
        return sinRespaldo.Count > 0 || sesion.Registro.UsoDatos ? sinRespaldo : _citasDeRespuesta.Respaldo(limpio, entrada.Secciones);
    }

    private MaterialConfidencial Confidencial(SesionPregunta sesion, EntradaConversacion entrada) =>
        new(
            _configuracion.MarcadorCanario,
            [ConstructorPrompts.Instrucciones(entrada.PromptSistema), .. DescripcionesDeHerramientas(sesion.Entrada.Usuario.Rol)],
            HerramientasAsistente.NombresInternos);

    private static IEnumerable<string> DescripcionesDeHerramientas(Rol rol) =>
        HerramientasAsistente.Definir(rol)
            .SelectMany(herramienta => herramienta.Parametros.Select(parametro => parametro.Descripcion).Prepend(herramienta.Descripcion));
}
using System.Text.RegularExpressions;
using TutorFlow.Core.Autorizacion;

namespace TutorFlow.Core.Asistente;

internal static partial class LimpiezaDeOraciones
{
    private const int PalabrasMinimasPorOracion = 3;
    private const string EspacioEnBlanco = " ";

    private static readonly TimeSpan LimiteRegex = TimeSpan.FromMilliseconds(TiempoLimiteRegex.Milisegundos);

    private static readonly (Regex Patron, string Reemplazo)[] ReglasDeSignos =
    [
        (new Regex(@"[\(\[][\s·,;:]*[\)\]]", RegexOptions.CultureInvariant, LimiteRegex), EspacioEnBlanco),
        (new Regex(@" {2,}", RegexOptions.CultureInvariant, LimiteRegex), EspacioEnBlanco),
        (new Regex(@"(?<!\d) +(?=[.,;:!?)])|(?<=\d) +(?=[;:!?)]|[.,](?!\d))", RegexOptions.CultureInvariant, LimiteRegex), string.Empty),
        (new Regex(@"(?<!\.)\.\.(?!\.)", RegexOptions.CultureInvariant, LimiteRegex), "."),
        (new Regex(@"[,;:]\.", RegexOptions.CultureInvariant, LimiteRegex), "."),
        (new Regex(@",,", RegexOptions.CultureInvariant, LimiteRegex), ","),
        (new Regex(@"^[\s:,;·]+", RegexOptions.CultureInvariant, LimiteRegex), string.Empty)
    ];

    public static string Depurar(string marcada) =>
        string.Concat(CorteDeOracion().Split(marcada).Select(Oracion)).Trim();

    private static string Oracion(string oracion) =>
        oracion.Contains(ReferenciasEscritas.Marca, StringComparison.Ordinal) ? Depurada(oracion) : oracion;

    private static string Depurada(string marcada)
    {
        var texto = marcada.Replace(ReferenciasEscritas.Marca, ' ');
        if (TerminaEnAtribucionHuerfana(texto) || HuecoTrasPalabraIncompleta(marcada) || QuedaCorta(texto))
        {
            return string.Empty;
        }

        var margen = EspaciosIniciales().Match(texto).Value;
        var cola = EspaciosFinales().Match(texto).Value;
        var cuerpo = ReglasDeSignos.Aggregate(texto.Trim(), (actual, regla) => regla.Patron.Replace(actual, regla.Reemplazo)).Trim();
        return margen + Capitalizar(cuerpo, marcada) + cola;
    }

    private static bool TerminaEnAtribucionHuerfana(string texto) =>
        AtribucionHuerfana().IsMatch(PuntuacionFinal().Replace(texto, string.Empty));

    private static bool HuecoTrasPalabraIncompleta(string marcada) =>
        Enumerable.Range(0, marcada.Length)
            .Where(indice => marcada[indice] == ReferenciasEscritas.Marca)
            .Any(indice => PalabraIncompleta().IsMatch(NormalizadorTexto.Normalizar(marcada[..indice]).TrimEnd()));

    private static bool QuedaCorta(string texto) =>
        TerminaConPuntoFinal().IsMatch(texto.TrimEnd()) && PalabraOCifra().Count(texto) < PalabrasMinimasPorOracion;

    private static string Capitalizar(string cuerpo, string marcada)
    {
        var inicio = LetraTrasLaMarca().Match(marcada);
        return inicio.Success && cuerpo.Length > 0 && char.IsLower(cuerpo[0]) && cuerpo[0] == inicio.Groups["letra"].Value[0]
            ? char.ToUpperInvariant(cuerpo[0]) + cuerpo[1..]
            : cuerpo;
    }

    [GeneratedRegex(@"(?<=\n)|(?<=[.!?])(?=\s|$)", RegexOptions.CultureInvariant, TiempoLimiteRegex.Milisegundos)]
    private static partial Regex CorteDeOracion();

    [GeneratedRegex(@"^\s*", RegexOptions.CultureInvariant, TiempoLimiteRegex.Milisegundos)]
    private static partial Regex EspaciosIniciales();

    [GeneratedRegex(@"\s*$", RegexOptions.CultureInvariant, TiempoLimiteRegex.Milisegundos)]
    private static partial Regex EspaciosFinales();

    [GeneratedRegex(@"[\s.,;:!?)\]]+$", RegexOptions.CultureInvariant, TiempoLimiteRegex.Milisegundos)]
    private static partial Regex PuntuacionFinal();

    [GeneratedRegex(@"[.!?]\z", RegexOptions.CultureInvariant, TiempoLimiteRegex.Milisegundos)]
    private static partial Regex TerminaConPuntoFinal();

    [GeneratedRegex(@"[\p{L}\p{N}]+", RegexOptions.CultureInvariant, TiempoLimiteRegex.Milisegundos)]
    private static partial Regex PalabraOCifra();

    [GeneratedRegex(@"^[\s]*[\s]*(?<letra>\p{Ll})", RegexOptions.CultureInvariant, TiempoLimiteRegex.Milisegundos)]
    private static partial Regex LetraTrasLaMarca();

    [GeneratedRegex(
        @"(?<![\p{L}\p{N}])(?:a|al|con|de|del|en|por|segun|sobre|esta|estan|figuran?|aparecen?|respaldad[oa]s?|se\s+respaldan?"
        + @"|se\s+basan?|basad[oa]s?|se\s+encuentran?|provienen?|se\s+establecen?|establecid[oa]s?|se\s+indican?|consulta|ver)\z",
        RegexOptions.CultureInvariant, TiempoLimiteRegex.Milisegundos)]
    private static partial Regex PalabraIncompleta();

    [GeneratedRegex(
        @"(?<![\p{L}\p{N}])(?:a|al|con|de|del|en|por|según|segun|sobre|respaldad[oa]s?|se\s+respaldan?|se\s+basan?|basad[oa]s?|se\s+encuentran?"
        + @"|provienen?|se\s+establecen?|establecid[oa]s?|se\s+indican?|consulta|ver)\z",
        RegexOptions.IgnoreCase | RegexOptions.CultureInvariant, TiempoLimiteRegex.Milisegundos)]
    private static partial Regex AtribucionHuerfana();
}
using TutorFlow.Core.Autorizacion;

namespace TutorFlow.Core.Asistente;

internal sealed class OracionGenerica
{
    private const string Hay = "hay";
    private const int PalabrasDePorInasistencia = 2;

    private static readonly HashSet<string> Marcadores = new(StringComparer.Ordinal)
    {
        "tu", "tus", "te", "ti", "tienes", "tengo", "mi", "mis", "me", "llevas", "usted", "perdiste", "perdi", "reprobaste", "dos", "tres", "cuatro"
    };

    private static readonly HashSet<string> AntecesoresDeHay = new(StringComparer.Ordinal) { "si", "que" };

    private readonly BloqueDeTexto _bloque;
    private readonly IReadOnlyList<TokenTexto> _tokens;
    private readonly bool _esEstudiante;
    private readonly IReadOnlyList<IReadOnlyList<string>> _identificadoresDelUsuario;

    public OracionGenerica(BloqueDeTexto bloque, IReadOnlyList<TokenTexto> tokens, Usuario usuario, DirectorioAcademico directorio)
    {
        _bloque = bloque;
        _tokens = tokens;
        _esEstudiante = usuario.Rol == Rol.Estudiante;
        _identificadoresDelUsuario = IdentificadoresDe(usuario, directorio);
    }

    public bool Es(FormaDePerdida forma) =>
        _esEstudiante && !TieneMarcadorPersonal() && TienePalabrasAjenas(forma);

    private static List<IReadOnlyList<string>> IdentificadoresDe(Usuario usuario, DirectorioAcademico directorio)
    {
        var nombre = directorio.Estudiantes.FirstOrDefault(estudiante => estudiante.Id == usuario.Id)?.Nombre;
        var identificadores = new List<IReadOnlyList<string>> { TokenizadorTexto.Valores(usuario.Id) };
        identificadores.AddRange(nombre is null ? [] : [TokenizadorTexto.Valores(nombre)]);
        return identificadores;
    }

    private bool TieneMarcadorPersonal() =>
        Enumerable.Range(0, _tokens.Count).Any(EsMarcadorEn)
        || _identificadoresDelUsuario.Any(secuencia => TokenizadorTexto.BuscarSecuencia(_tokens, secuencia) >= 0);

    private bool EsMarcadorEn(int indice) =>
        Marcadores.Contains(_tokens[indice].Valor)
        || (_tokens[indice].Valor == Hay && (indice == 0 || !AntecesoresDeHay.Contains(_tokens[indice - 1].Valor)));

    private bool TienePalabrasAjenas(FormaDePerdida forma)
    {
        var finDeLaForma = forma.Fin + (forma.PorInasistencia ? PalabrasDePorInasistencia : 0);
        return Enumerable.Range(0, _tokens.Count)
            .Any(indice => _tokens[indice].Inicio >= _bloque.InicioDeLaOracion && (indice < forma.Inicio || indice > finDeLaForma));
    }
}
using System.Text.RegularExpressions;
using TutorFlow.Core.Conocimiento;

namespace TutorFlow.Core.Asistente;

internal static partial class AtribucionGenerica
{
    private const string GrupoReglamento = "reglamento";
